package nl.smartstreamlabs.sbwdroneconfig;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import net.minecraft.world.phys.*;
public class NtGeometryTest {
 static List<Vec3> route(double... xyz){List<Vec3> r=new ArrayList<>();for(int i=0;i<xyz.length;i+=3)r.add(new Vec3(xyz[i],xyz[i+1],xyz[i+2]));return r;}
 static NtGeometry.Plan plan(List<Vec3> points,boolean sides){var s=new NtGeometry.Settings(6,4.5,6,10,sides);var p=new NtGeometry.Path(points,s);return new NtGeometry.Plan(points,s,0,Collections.nCopies(p.stations.length,0d),Collections.nCopies(p.stations.length,0d),p.errors);}
 static boolean hit(NtGeometry.Plan plan,AABB box,Vec3 delta){var p=new NtGeometry.Path(plan.points(),plan.settings());for(var t:NtGeometry.triangles(NtGeometry.panels(p,plan)))if(Double.isFinite(NtGeometry.sweep(box,delta,t)))return true;return false;}
 @Test void roundedRouteEndpointsAndContinuousFrames(){var cfg=NtGeometry.Settings.defaults();var p=new NtGeometry.Path(route(0,0,0,0,0,24,24,0,24),cfg);assertEquals(Vec3.ZERO,p.at(0));assertEquals(new Vec3(24,0,24),p.at(p.length));assertTrue(p.length>44&&p.length<45);assertTrue(p.errors.isEmpty());for(double s=.2;s<p.length;s+=.2)assertTrue(p.frame(s).n().dot(p.frame(s-.2).n())>.95);}
 @Test void outsidePostSpacingIsBoundedInBends(){var s=NtGeometry.Settings.defaults();var p=new NtGeometry.Path(route(0,0,0,0,0,24,24,0,24),s);for(int i=1;i<p.stations.length;i++)for(int sign:new int[]{-1,1}){double sum=0;Vec3 before=null;for(int j=0;j<=100;j++){var f=p.frame(p.stations[i-1]+(p.stations[i]-p.stations[i-1])*j/100);Vec3 at=f.p().add(f.n().scale(p.half*sign));if(before!=null)sum+=at.distanceTo(before);before=at;}assertTrue(sum<=s.spacing()+.03,"Outside spacing: "+sum);}}
 @Test void clearanceIncludesBothSagTermsAndSlopes(){var plan=plan(route(0,0,0,18,3,18,36,5,18),true);var p=new NtGeometry.Path(plan.points(),plan.settings());for(int bay=0;bay<p.stations.length-1;bay++)for(int i=0;i<=100;i++)for(double u:new double[]{-1,0,1}){double s=p.stations[bay]+(p.stations[bay+1]-p.stations[bay])*i/100;assertTrue(NtGeometry.roof(p,plan,bay,s,u).y-p.frame(s).p().y>=4.5-1e-8);}}
 @Test void baySeamsCoincideExactly(){var plan=plan(route(0,0,0,0,0,24,24,0,24),true);var p=new NtGeometry.Path(plan.points(),plan.settings());for(int b=1;b<p.stations.length-1;b++)for(int i=0;i<=16;i++)assertEquals(NtGeometry.roof(p,plan,b-1,p.stations[b],i/8.0-1),NtGeometry.roof(p,plan,b,p.stations[b],i/8.0-1));}
 @Test void fullVolumeCatchesFastAndGrazingRoofHits(){var plan=plan(route(0,0,0,0,0,12),false);assertTrue(hit(plan,new AABB(-.2,12,5.8,.2,12.4,6.2),new Vec3(0,-24,0)));assertTrue(hit(plan,new AABB(3.1,12,5.8,3.5,12.4,6.2),new Vec3(0,-24,0)));assertFalse(hit(plan,new AABB(3.3,12,5.8,3.7,12.4,6.2),new Vec3(0,-24,0)));}
 @Test void roofOnlySideNetsAndOpenEndsHaveDifferentProtection(){var pts=route(0,0,0,0,0,12);assertFalse(hit(plan(pts,false),new AABB(-8,1,5,-7,2,6),new Vec3(16,0,0)));assertTrue(hit(plan(pts,true),new AABB(-8,1,5,-7,2,6),new Vec3(16,0,0)));assertFalse(hit(plan(pts,true),new AABB(-1,0,-5,1,3,-3),new Vec3(0,0,24)));}
 @Test void invalidAndSelfCrossingRoutesAreRejected(){assertThrows(IllegalArgumentException.class,()->new NtGeometry.Path(route(0,0,0,0,0,0),NtGeometry.Settings.defaults()));assertThrows(IllegalArgumentException.class,()->new NtGeometry.Path(route(0,0,0,0,0,12,0,0,0),NtGeometry.Settings.defaults()));var tight=new NtGeometry.Path(route(0,0,0,0,0,3,3,0,3),NtGeometry.Settings.defaults());assertFalse(tight.errors.isEmpty());var crossing=new NtGeometry.Path(route(-20,0,-20,20,0,20,40,0,20,20,0,-20,-20,0,20),NtGeometry.Settings.defaults());assertFalse(crossing.errors.isEmpty());assertThrows(IllegalArgumentException.class,()->new NtGeometry.Path(route(0,0,0,0,0,300),NtGeometry.Settings.defaults()));}
 @Test void localDirectionsRemainStableAtWorldBorder(){var p=new NtGeometry.Path(route(29999000,200,29999000,29999000,202,29999024,29999024,204,29999024),NtGeometry.Settings.defaults());assertTrue(p.errors.isEmpty());assertEquals(1,p.frame(10).n().length(),1e-10);}
 @Test void savedTunnelAndPlanRoundTrip(){var p=plan(route(0,0,0,0,0,12),true);var t=new NtTunnel(UUID.randomUUID(),UUID.randomUUID(),7,"minecraft:overworld",p,12,30,2);var copy=NtTunnel.load(t.save());assertEquals(t,copy);assertEquals(p.fingerprint(),copy.plan().fingerprint());var s=new NtStore();s.put(t);assertNotNull(s.hit(new AABB(-.2,12,5,.2,12.4,6),new Vec3(0,-24,0)));s.remove(t.id());assertNull(s.hit(new AABB(-.2,12,5,.2,12.4,6),new Vec3(0,-24,0)));}
}
